function UITalentMaterialLevelSelectionNode:Refresh(buffId, questId, cb, selectCb)
    if checkNumber(buffId) == 0 or checkNumber(questId) == 0 then
        return
    end
    self._curBuffId = buffId
    self._curQuestId = questId
