function UITalentMaterialLevelSelectionNode:FillSelf()
    local vo = QuestConfMgr:GetInstance():GetTalentBuffVo(self._curBuffId)
    if not vo then
        return
    end

    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if questVo then
        local num = talentQuestComponent:GetCurCopyRewardOutPut()
        if num == 0 then
            num = QuestConfMgr:GetInstance():GetTalentBaseRewardNum(questVo.group)
        end
        local id = QuestConfMgr:GetInstance():GetTalentRewardId()

        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        CfUtils.RefeshGoodGo(self.GoodNode, id, CfUtils.Ceil(num * (vo.rewardRatio)), 0.65, nil, function()
            GameUtils.ShowCommonTipsBoard(self.GoodNode, goodsVo.name, nil, nil, id, false)
        end)
    end

    local upBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(vo.buffId)
    if not upBuffVo then
        return
    end
    CfUtils.FillText(self.TxtState, upBuffVo.desc)
    self:FillSelect(false)
    self.FontStyleButton:ResetFontStyle("B13")


    local curQuestId = talentQuestComponent:GetCurQuestId()
    --if checkNumber(curQuestId) > 0 then
        print(vo.rewardRatio * 100)
        CfUtils.FillText(self.TxtNumber, CfUtils.Ceil((vo.rewardRatio * 100)).."%")
        KTool.SetActive(self.TxtIncrease, true)
    --else
        --KTool.SetActive(self.TxtIncrease, false)
    --end
end

